"""Validate generated bytes and record provenance; never edit generated pixels."""
from pathlib import Path
import json,hashlib
from PIL import Image
R=Path(__file__).resolve().parents[2]
import sys
sys.path.insert(0, str(R / "tools"))
from privacy import public_source
manifest=R/'assets/manifest.json'
M=json.loads(manifest.read_text())
C=json.loads((R/'data/catalog.json').read_text())
raw=json.loads((R/'art_sources/originals/generated-raw-paths.json').read_text())
for key,path in raw.items():
    entry=M['items'][key]
    p=R/'assets/skins/chibi/items'/f'{key}.png'
    assert p.read_bytes()==Path(path).read_bytes(),key+' altered generated bytes'
    im=Image.open(p)
    assert 'A' in im.getbands(),key+' missing alpha'
    alpha=im.getchannel('A')
    assert alpha.getextrema()[0]==0 and alpha.getextrema()[1]==255,key+' missing transparent border'
    entry.update(path=str(p.relative_to(R)),raw_path=public_source(path),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),
                 dimensions=list(im.size),has_alpha=True,alpha_bounds=list(alpha.getbbox()),
                 status='generated_reviewed',generator='built_in_image_gen',prompt=f'art_sources/originals/{key}-prompt.txt')
for key,d in C['items'].items():
    if not d.get('v60',{}).get('active') or 'bag' in d['tags']:continue
    e=M['items'][key]
    if 'variant_of' in e:
        base=M['items'][e['variant_of']]
        for field in ('path','raw_path','sha256','dimensions','has_alpha','alpha_bounds','status','generator','prompt'):
            if field in base:e[field]=base[field]
    e.update(shape=d['shape'],tags=d['tags'])
    assert (R/e['path']).is_file(),key
    assert (R/d['asset_path']).is_file(),key+' original missing'
manifest.write_text(json.dumps(M,ensure_ascii=False,indent=2)+'\n')
print('19 generated assets verified; all 74 active non-pocket icons have Q/original art.')
